168	// select a user page to write to disk (NRU), returns pa
169	ptr_t selete_page()
170	{
171	    static int clock_hand = 0;
172	
173	    /* NRU (clock) algorithm: give pages whose accessed bit is set
174	       a second chance by clearing the bit; the first unpinned valid
175	       page with a clear accessed bit is selected as the victim */
176	    while (1) {
177	        int i = clock_hand;
178	        clock_hand = (clock_hand + 1) % USER_PAGE_NUM;
179	
180	        if (user_page[i].valid == 0 || user_page[i].pin != 0) {
181	            continue;
182	        }
183	
184	        ptr_t pa = num2pa(i);
185	        PTE *pte = find_pte_by_pa(user_page[i].pgtable, pa);
186	        if (pte == NULL) {
187	            /* not mapped anymore, safe to reuse */
188	            return pa;
189	        }
190	        if (get_attribute(*pte, _PAGE_ACCESSED)) {
191	            clear_attribute(pte, _PAGE_ACCESSED);
192	        } else {
193	            return pa;
194	        }
195	    }
196	}
