198	void write_to_sd(ptr_t pa)
199	{
200	    /* search for a free disk slot in the swap area */
201	    int i;
202	    for (i = 0; i < DISK_PAGE_NUM; i++) {
203	        if (disk_page[i].valid == 0) {
204	            break;
205	        }
206	    }
207	    assert(i != DISK_PAGE_NUM);
208	    disk_page[i].valid = 1;
209	
210	    /* write the page content to the swap area on the SD card */
211	    sbi_sd_write(pa, SECTORS_PER_PAGE, SWAP_BEGIN + i * SECTORS_PER_PAGE);
212	
213	    /* mark the corresponding PTE as swapped out: the disk slot id is
214	       recorded in the PFN field and the software bit is set */
215	    PTE *pte = find_pte_by_pa(user_page[pa2num(pa)].pgtable, pa);
216	    assert(pte != NULL);
217	    set_pfn(pte, i);
218	    clear_attribute(pte, _PAGE_PRESENT);
219	    set_attribute(pte, _PAGE_SOFT);
220	    flush_tlb_all();
221	
222	    /* the physical page is free now */
223	    user_page[pa2num(pa)].valid = 0;
224	}
