237	/*
238	 * Virtual Memory Layout
239	 * 0x0_0000_1000 ~ 0x0_0001_0000: share
240	 * 0x0_0001_0000 ~ 0x0_0001_3000: code
241	 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
242	 */
243	PTE* init_page_table()
244	{
245	    /* allocate a fresh page directory (returns pa, already cleared) */
246	    PTE *pgdir = alloc_pgdir_page();
247	    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
248	    PTE *kernel_pgdir_kva = (PTE *)pa2kva(PGDIR_PA);
249	
250	    /* copy the kernel large-page mappings so that the kernel remains
251	       reachable (traps, kernel stacks, pa2kva) while this process runs;
252	       both entries share the kernel's second-level table */
253	    pgdir_kva[0x001] = kernel_pgdir_kva[0x001];
254	    pgdir_kva[0x101] = kernel_pgdir_kva[0x101];
255	
256	    return pgdir;
257	}
