259	void free_process_user_page(PTE* pgdir)
260	{
261	    PTE *l2_table = (PTE *)pa2kva((uintptr_t)pgdir);
262	
263	    for (int i = 0; i < NUM_PTE_ENTRY; i++) {
264	        if (i == 0x001 || i == 0x101) {
265	            continue;   /* keep the shared kernel mappings */
266	        }
267	        if (!get_attribute(l2_table[i], _PAGE_PRESENT)) {
268	            continue;
269	        }
270	        PTE *l1_table = (PTE *)pa2kva(get_pa(l2_table[i]));
271	        for (int j = 0; j < NUM_PTE_ENTRY; j++) {
272	            if (!get_attribute(l1_table[j], _PAGE_PRESENT)) {
273	                continue;
274	            }
275	            PTE *l0_table = (PTE *)pa2kva(get_pa(l1_table[j]));
276	            for (int k = 0; k < NUM_PTE_ENTRY; k++) {
277	                PTE pte = l0_table[k];
278	                if (get_attribute(pte, _PAGE_SOFT)) {
279	                    /* swapped-out page: release the disk slot */
280	                    disk_page[get_pfn(pte)].valid = 0;
281	                    continue;
282	                }
283	                if (!get_attribute(pte, _PAGE_PRESENT)) {
284	                    continue;
285	                }
286	                uintptr_t pa = get_pa(pte);
287	                uintptr_t va = ((uintptr_t)i << VPN2_SHIFT) |
288	                               ((uintptr_t)j << VPN1_SHIFT) |
289	                               ((uintptr_t)k << VPN0_SHIFT);
290	                if (va >= SHM_BASE && va < SHM_END) {
291	                    /* shared memory page: only release the physical page
292	                       when no process maps it anymore */
293	                    for (int s = 0; s < SHM_PAGE_NUM; s++) {
294	                        if (shm_page[s].count > 0 && shm_page[s].pa == pa) {
295	                            if (--shm_page[s].count == 0) {
296	                                free_user_page(pa);
297	                            }
298	                            break;
299	                        }
300	                    }
301	                } else {
302	                    free_user_page(pa);
303	                }
304	            }
305	            free_pgdir_page(get_pa(l1_table[j]));
306	        }
307	        free_pgdir_page(get_pa(l2_table[i]));
308	    }
309	
310	    free_pgdir_page((uintptr_t)pgdir);
311	}
