399	void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
400	{
401	    pcb_t *cur = current_running[cpu_id];
402	    uintptr_t va = ROUNDDOWN(stval, PAGE_SIZE);
403	
404	    PTE *pte = walk_page_table(va, (uintptr_t)cur->pgdir, 1);
405	    assert(pte != NULL);
406	
407	    if (get_attribute(*pte, _PAGE_SOFT)) {
408	        /* the page was swapped out to disk: swap it back in */
409	        int disk_id = get_pfn(*pte);
410	        ptr_t pa = alloc_user_page(0, cur->pgdir);
411	        sbi_sd_read(pa, SECTORS_PER_PAGE, SWAP_BEGIN + disk_id * SECTORS_PER_PAGE);
412	        disk_page[disk_id].valid = 0;
413	
414	        set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
415	        clear_attribute(pte, _PAGE_SOFT);
416	        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
417	                      _PAGE_EXEC | _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
418	    } else {
419	        /* demand paging: allocate a fresh zeroed anonymous page */
420	        ptr_t pa = alloc_user_page(0, cur->pgdir);
421	        memset((void *)pa2kva(pa), 0, PAGE_SIZE);
422	
423	        set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
424	        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
425	                      _PAGE_EXEC | _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
426	    }
427	
428	    flush_tlb_all();
429	}

