130	    pcb_t *exit_pcb = current_running[cpu_id];
131	
132	    /* release all the binary semaphores held by this process */
133	    while (exit_pcb->binsem_num > 0) {
134	        binsem_op(exit_pcb->binsem_id[exit_pcb->binsem_num - 1],
135	                  BINSEM_OP_UNLOCK);
136	    }
137	
138	    /* wake up all the processes waiting for this process */
139	    while (!list_empty(&exit_pcb->wait_list)) {
140	        do_unblock(exit_pcb->wait_list.next);
141	    }
