143	    if (exit_pcb->mode == ENTER_ZOMBIE_ON_EXIT) {
144	        /* become a zombie and wait to be reaped by waitpid */
145	        exit_pcb->status = TASK_ZOMBIE;
146	    } else {
147	        /* AUTO_CLEANUP_ON_EXIT: hand the pcb over to the reaper */
148	        exit_pcb->status = TASK_EXITED;
149	        list_add_tail(&exit_pcb->list, &kernel_pcb[0].wait_list);
150	    }
151	
152	    /* switch to another task */
