// block the pcb task into the block queue
void do_block(list_node_t *pcb_node, list_head *queue)
{
    list_del(pcb_node);
    list_add_tail(pcb_node, queue);
    list_entry(pcb_node, pcb_t, list)->status = TASK_BLOCKED;
}

// unblock the `pcb` from the block queue
void do_unblock(list_node_t *pcb_node)
{
    list_del(pcb_node);
    list_add_tail(pcb_node, &ready_queue);
    list_entry(pcb_node, pcb_t, list)->status = TASK_READY;
    list_entry(pcb_node, pcb_t, list)->ready_tick = get_ticks();
}

list_node_t* max_priority_node(void)
{
    list_node_t *node;
    list_node_t *max_node = NULL;
    pcb_t *max_pcb = NULL;
    pcb_t *pcb;

    /* scan the ready queue: only tasks whose hart mask covers this
       core are considered; higher priority value wins, and for equal
       priorities the task that became ready first wins */
    for (node = ready_queue.next; node != &ready_queue; node = node->next) {
        pcb = list_entry(node, pcb_t, list);
        if (!(pcb->mask & (1lu << cpu_id))) {
            continue;
        }
        if (max_pcb == NULL ||
            pcb->priority > max_pcb->priority ||
            (pcb->priority == max_pcb->priority &&
             pcb->ready_tick < max_pcb->ready_tick)) {
            max_pcb = pcb;
            max_node = node;
        }
    }

    return max_node;
}

