list_node_t* max_priority_node(void)
{
    list_node_t *node;
    list_node_t *max_node = NULL;
    pcb_t *max_pcb = NULL;
    pcb_t *pcb;

    /* scan the ready queue: only tasks whose hart mask covers this
       core are considered; higher priority value wins, and for equal
       priorities the task that became ready first wins */
    for (node = ready_queue.next; node != &ready_queue; node = node->next) {
        pcb = list_entry(node, pcb_t, list);
        if (!(pcb->mask & (1lu << cpu_id))) {
            continue;
        }
        if (max_pcb == NULL ||
            pcb->priority > max_pcb->priority ||
            (pcb->priority == max_pcb->priority &&
             pcb->ready_tick < max_pcb->ready_tick)) {
            max_pcb = pcb;
            max_node = node;
        }
    }

    return max_node;
}

