long do_net_recv(uintptr_t addr, size_t length, int num_packet, size_t* frLength)
{
    if (net_poll_mode) {
        /* polling mode: arm the receiver and spin until all the
           packets have arrived */
        EmacPsRecv(&EmacPsInstance, rx_buffers, num_packet);
        EmacPsWaitRecv(&EmacPsInstance, num_packet, rx_len);

        /* copy the received packets into the user buffer */
        enable_sum();
        uintptr_t rx_curr = addr;
        long total = 0;
        for (int i = 0; i < num_packet; i++) {
            memcpy((uint8_t*)rx_curr, (uint8_t*)&rx_buffers[i], rx_len[i]);
            frLength[i] = rx_len[i];
            rx_curr += rx_len[i];
            total += rx_len[i];
        }
        disable_sum();

        return total;
    } else {
        /* interrupt mode: record the transaction, arm the receiver
           and block until the irq handler completes the transfer */
        _addr = addr;
        _num_packet = num_packet;
        _frLength = frLength;
        recv_transaction = 1;

        EmacPsRecv(&EmacPsInstance, rx_buffers, num_packet);

        do_block(&current_running[cpu_id]->list, &net_recv_queue);
        scheduler();

        /* the irq handler has copied the packets and filled rx_len[] */
        long total = 0;
        for (int i = 0; i < num_packet; i++) {
            total += rx_len[i];
        }
        return total;
    }
}

void do_net_send(uintptr_t addr, size_t length)
{
    /* copy the packet from the user buffer into the tx buffer */
    enable_sum();
    memcpy((uint8_t*)&tx_buffer, (uint8_t*)addr, length);
    disable_sum();

    if (net_poll_mode) {
        /* polling mode: transmit and spin until the packet is sent */
        EmacPsSend(&EmacPsInstance, &tx_buffer, length);
        EmacPsWaitSend(&EmacPsInstance);
    } else {
        /* interrupt mode: transmit and block until the irq handler
           signals the completion of the transfer */
        send_transaction = 1;

        EmacPsSend(&EmacPsInstance, &tx_buffer, length);

        do_block(&current_running[cpu_id]->list, &net_send_queue);
        scheduler();
    }
}

void do_net_irq_mode(int mode)
{
    /* mode == 0: polling mode, otherwise: interrupt mode */
    net_poll_mode = (mode == 0);
}

