/* find the entry named `name` in the directory `dir_inode_id`;
   on success returns 1 and stores the entry in `out`, the block id
   holding it in `out_block` and its index in `out_index` (the latter
   two may be NULL) */
int find_in_dir(uint16_t dir_inode_id, const char* name, dir_entry_t* out,
                uint32_t* out_block, int* out_index)
{
    inode_t dir_inode = *(inode_t*)read_inode(dir_inode_id);

    for (int b = 0; b < 10 && (uint32_t)(b * 4096) < dir_inode.size; b++) {
        read_block(dir_inode.direct_blocks[b]);
        dir_t *dir = (dir_t*)BLOCK_CACHE;
        for (int i = 0; i < 128; i++) {
            if (dir->entry[i].type != EMPTY &&
                strcmp((char*)dir->entry[i].name, name) == 0) {
                *out = dir->entry[i];
                if (out_block != 0) {
                    *out_block = dir_inode.direct_blocks[b];
                }
                if (out_index != 0) {
                    *out_index = i;
                }
                return 1;
            }
        }
    }
    return 0;
}

/* add an entry to the directory `dir_inode_id`, allocating a new
   block for the directory when all the existing ones are full */
int add_dir_entry(uint16_t dir_inode_id, uint8_t type, const char* name,
                  uint16_t inode_id)
{
    inode_t *dir_inode = (inode_t*)read_inode(dir_inode_id);

    for (int b = 0; b < 10; b++) {
        if ((uint32_t)(b * 4096) >= dir_inode->size) {
            /* all the existing blocks are full: allocate a new one */
            uint32_t nb = alloc_block();
            if (nb == 0xffffffff) {
                return 0;
            }
            dir_inode->direct_blocks[b] = nb;
            dir_inode->size += 4096;
            write_inode(dir_inode_id);

            memset((void*)BLOCK_CACHE, 0, 4096);
            dir_t *dir = (dir_t*)BLOCK_CACHE;
            dir->entry[0].type = type;
            strcpy((char*)dir->entry[0].name, name);
            dir->entry[0].inode = inode_id;
            write_block(nb);
            return 1;
        }

        uint32_t bid = dir_inode->direct_blocks[b];
        read_block(bid);
        dir_t *dir = (dir_t*)BLOCK_CACHE;
        for (int i = 0; i < 128; i++) {
            if (dir->entry[i].type == EMPTY) {
                dir->entry[i].type = type;
                strcpy((char*)dir->entry[i].name, name);
                dir->entry[i].inode = inode_id;
                write_block(bid);
                return 1;
            }
        }
    }
    return 0;
}

int mkfs(int print)
{
    if (print) {
        prints("[FS] Start initializing file system.\n");
        prints("[FS] Setting superblock...\n");
        prints("[FS] magic: 0x%lx\n", MAGIC);
        prints("[FS] superblock: id %d, num %d\n", SUPERBLOCK_ID, 1);
        prints("[FS] blockmap: id %d, num %d\n", BLOCKMAP_BEGIN_ID, 64);
        prints("[FS] inodemap: id %d, num %d\n", INODEMAP_ID, 1);
        prints("[FS] inode: id %d, num %d\n", INODE_BEGIN_ID, 4096);
        prints("[FS] block: id %d, num %d\n", BLOCK_BEGIN_ID, 262144);
        prints("[FS] Initializing root directory...\n");
        prints("[FS] root inode %d, root block %d\n", 0, 0);
        prints("[FS] File system initialized successfully!\n");
    }

    /* initialize the superblock */
    superblock->magic = MAGIC;
    superblock->superblock_id = SUPERBLOCK_ID;
    superblock->superblock_num = 1;
    superblock->blockmap_id = BLOCKMAP_BEGIN_ID;
    superblock->blockmap_num = 64;
    superblock->inodemap_id = INODEMAP_ID;
    superblock->inodemap_num = 1;
    superblock->inode_id = INODE_BEGIN_ID;
    superblock->inode_num = 4096;       /* 512 sectors * 8 inodes */
    superblock->block_id = BLOCK_BEGIN_ID;
    superblock->block_num = 262144;     /* 2097152 sectors / 8 */
    superblock->root_inode_id = 0;
    superblock->root_block_id = 0;
    superblock->used_inode_num = 1;
    superblock->used_block_num = 1;
    write_superblock();

    /* clear the bitmaps and mark the root inode/block as used */
    memset((void*)BLOCKMAP_CACHE, 0, 64 * 512);
    *(uint8_t*)BLOCKMAP_CACHE = 0x1;
    write_blockmap();

    memset((void*)INODEMAP_CACHE, 0, 512);
    *(uint8_t*)INODEMAP_CACHE = 0x1;
    write_inodemap();

    /* initialize the root inode */
    memset((void*)INODE_CACHE, 0, 512);
    inode_t *root_inode = (inode_t*)INODE_CACHE;
    root_inode->mode = DIR;
    root_inode->owner = 0;
    root_inode->size = 4096;
    root_inode->direct_blocks[0] = 0;
    root_inode->link = 1;
    write_inode(0);

    /* initialize the root directory block with "." and ".." */
    memset((void*)BLOCK_CACHE, 0, 4096);
    dir_t *root_dir = (dir_t*)BLOCK_CACHE;
    root_dir->entry[0].type = DIR;
    strcpy((char*)root_dir->entry[0].name, ".");
    root_dir->entry[0].inode = 0;
    root_dir->entry[1].type = DIR;
    strcpy((char*)root_dir->entry[1].name, "..");
    root_dir->entry[1].inode = 0;
    write_block(0);

    /* the current working directory is the root directory */
    current_dir_inode = 0;
    current_dir_block = 0;

    return 1;
}

