#include <os/fs.h>
#include <os/disk.h>
#include <os/file.h>
#include <os/sched.h>
#include <os/irq.h>
#include <os/string.h>
#include <assert.h>

fd_t fd_list[10];

#define DIRECT_BLOCK_NUM 10
#define PTRS_PER_BLOCK (4096 / sizeof(uint32_t))

/* return the block id of the file block `idx` of `inode`;
   when `create` is non-zero, missing (in)direct blocks are allocated.
   Returns 0 when the block does not exist or the disk is full
   (block 0 is owned by the root directory, so files never use it) */
uint32_t file_block_id(inode_t* inode, uint16_t inode_id, uint32_t idx, int create)
{
    if (idx < DIRECT_BLOCK_NUM) {
        if (inode->direct_blocks[idx] == 0) {
            if (!create) {
                return 0;
            }
            uint32_t nb = alloc_block();
            if (nb == 0xffffffff) {
                return 0;
            }
            inode->direct_blocks[idx] = nb;
            write_inode(inode_id);

            memset((void*)BLOCK_CACHE, 0, 4096);
            write_block(nb);
        }
        return inode->direct_blocks[idx];
    }

    /* indirect blocks: each one stores 1024 block ids */
    idx -= DIRECT_BLOCK_NUM;
    if (idx >= 2 * PTRS_PER_BLOCK) {
        return 0;   /* file too large */
    }
    int ind = idx / PTRS_PER_BLOCK;
    uint32_t off = idx % PTRS_PER_BLOCK;

    if (inode->indirect_blocks[ind] == 0) {
        if (!create) {
            return 0;
        }
        uint32_t nb = alloc_block();
        if (nb == 0xffffffff) {
            return 0;
        }
        inode->indirect_blocks[ind] = nb;
        write_inode(inode_id);

        memset((void*)BLOCK_CACHE, 0, 4096);
        write_block(nb);
    }

    uint32_t ind_bid = inode->indirect_blocks[ind];
    read_block(ind_bid);
    uint32_t *table = (uint32_t*)BLOCK_CACHE;
    if (table[off] == 0) {
        if (!create) {
            return 0;
        }
        uint32_t nb = alloc_block();
        if (nb == 0xffffffff) {
            return 0;
        }
        table[off] = nb;
        write_block(ind_bid);

        memset((void*)BLOCK_CACHE, 0, 4096);
        write_block(nb);
        return nb;
    }

    return table[off];
}

int do_touch(char* filename)
{
    char name[32];
    fs_get_name(name, filename);
    if (name[0] == '\0') {
        return 0;
    }

    /* the file must not exist yet */
    dir_entry_t entry;
    if (find_in_dir(current_dir_inode, name, &entry, 0, 0)) {
        return 0;
    }

    /* allocate an inode for the new empty file */
    uint16_t new_inode = alloc_inode();
    if (new_inode == 0xffff) {
        return 0;
    }

    inode_t *inode = (inode_t*)read_inode(new_inode);
    memset(inode, 0, sizeof(inode_t));
    inode->mode = FILE;
    inode->owner = 0;
    inode->size = 0;
    inode->link = 1;
    write_inode(new_inode);

    /* add the entry to the current directory */
    if (!add_dir_entry(current_dir_inode, FILE, name, new_inode)) {
        free_inode(new_inode);
        return 0;
    }

    return 1;
}

int do_cat(char* filename, char* buffer)
{
    char name[32];
    fs_get_name(name, filename);
    if (name[0] == '\0') {
        return 0;
    }

    dir_entry_t entry;
    if (!find_in_dir(current_dir_inode, name, &entry, 0, 0) ||
        entry.type != FILE) {
        return 0;
    }

    /* read the whole file into the user buffer */
    inode_t inode = *(inode_t*)read_inode(entry.inode);
    uint32_t size = inode.size;
    uint32_t done = 0;
    while (done < size) {
        uint32_t idx = done / 4096;
        uint32_t off = done % 4096;
        uint32_t chunk = 4096 - off;
        if (chunk > size - done) {
            chunk = size - done;
        }

        uint32_t bid = file_block_id(&inode, entry.inode, idx, 0);
        if (bid == 0) {
            break;
        }
        read_block(bid);
        enable_sum();
        memcpy((uint8_t*)buffer + done, (uint8_t*)BLOCK_CACHE + off, chunk);
        disable_sum();
        done += chunk;
    }

    enable_sum();
    buffer[done] = '\0';
    disable_sum();

    return 1;
}

int do_fopen(char* filename, int access)
{
    char name[32];
    fs_get_name(name, filename);
    if (name[0] == '\0') {
        return -1;
    }

    /* look up the file; create it when it is missing and the
       access mode allows writing */
    dir_entry_t entry;
    if (!find_in_dir(current_dir_inode, name, &entry, 0, 0)) {
        if (access == O_RDONLY) {
            return -1;
        }

        uint16_t new_inode = alloc_inode();
        if (new_inode == 0xffff) {
            return -1;
        }
        inode_t *inode = (inode_t*)read_inode(new_inode);
        memset(inode, 0, sizeof(inode_t));
        inode->mode = FILE;
        inode->owner = 0;
        inode->size = 0;
        inode->link = 1;
        write_inode(new_inode);

        if (!add_dir_entry(current_dir_inode, FILE, name, new_inode)) {
            free_inode(new_inode);
            return -1;
        }
        entry.inode = new_inode;
        entry.type = FILE;
    } else if (entry.type != FILE) {
        return -1;
    }

    /* allocate a file descriptor */
    for (int i = 0; i < 10; i++) {
        if (fd_list[i].access == O_EMPTY) {
            fd_list[i].inode = entry.inode;
            fd_list[i].access = access;
            fd_list[i].rd_pos = 0;
            fd_list[i].wr_pos = 0;
            return i;
        }
    }

    return -1;
}

int do_fread(int fd, char* buffer, int size)
{
    if (fd < 0 || fd >= 10 ||
        (fd_list[fd].access != O_RDONLY && fd_list[fd].access != O_RDWR)) {
        return 0;
    }

    uint16_t inode_id = fd_list[fd].inode;
    inode_t inode = *(inode_t*)read_inode(inode_id);

    /* clamp the read to the end of the file */
    uint64_t pos = fd_list[fd].rd_pos;
    if (pos >= inode.size) {
        return 0;
    }
    if (size > (int)(inode.size - pos)) {
        size = inode.size - pos;
    }

    int done = 0;
    while (done < size) {
        uint32_t idx = pos / 4096;
        uint32_t off = pos % 4096;
        uint32_t chunk = 4096 - off;
        if (chunk > (uint32_t)(size - done)) {
            chunk = size - done;
        }

        uint32_t bid = file_block_id(&inode, inode_id, idx, 0);
        if (bid == 0) {
            break;
        }
        read_block(bid);
        enable_sum();
        memcpy((uint8_t*)buffer + done, (uint8_t*)BLOCK_CACHE + off, chunk);
        disable_sum();

        pos += chunk;
        done += chunk;
    }

    fd_list[fd].rd_pos = pos;
    return done;
}

int do_fwrite(int fd, char* buffer, int size)
{
    if (fd < 0 || fd >= 10 ||
        (fd_list[fd].access != O_WRONLY && fd_list[fd].access != O_RDWR)) {
        return 0;
    }

    uint16_t inode_id = fd_list[fd].inode;
    inode_t *inode = (inode_t*)read_inode(inode_id);

    uint64_t pos = fd_list[fd].wr_pos;
    int done = 0;
    while (done < size) {
        uint32_t idx = pos / 4096;
        uint32_t off = pos % 4096;
        uint32_t chunk = 4096 - off;
        if (chunk > (uint32_t)(size - done)) {
            chunk = size - done;
        }

        uint32_t bid = file_block_id(inode, inode_id, idx, 1);
        if (bid == 0) {
            break;   /* disk full or file too large */
        }
        read_block(bid);
        enable_sum();
        memcpy((uint8_t*)BLOCK_CACHE + off, (uint8_t*)buffer + done, chunk);
        disable_sum();
        write_block(bid);

        pos += chunk;
        done += chunk;
    }

    /* grow the file size when the write went past the old end */
    if (pos > inode->size) {
        inode->size = pos;
        write_inode(inode_id);
    }

    fd_list[fd].wr_pos = pos;
    return done;
}

